import logging
import os
from plotly import offline, graph_objs, subplots
from taf.ul.chart.throughput.translator import (
    convert_bytes_to_mbps_with_time_interval,
    translate_percentage,
)


logger = logging.getLogger(__name__)


class AasyslogChartGenerator(object):
    def __init__(self, records=None):
        self.records = records
        self.figure = None
        self.min_cnt = 99999
        self.xlist = []
        self.cells = []

    def generate(
        self,
        direction,
        ca,
        theoretical_throughput,
        average_tolerance,
        minimum_tolerance,
        records=None,
        output_dir=None,
        log_name_prefix=None,
        time_interval=1.024
    ):
        """
        Generate a html type file, containing operational throughput data chart.
        Default output file name: [{date}]_{cell_id}_{direction}.html

        Args:
            direction: str, "UL" / "DL"
            ca: Bool, actCarrierAggregation, Define the chart should show data of each cell or combine togather.
            theoretical_throughput: str, target throughput value.(theory value) unit in Mbps!! E.G 2048.0
            average_tolerance: str, acceptable percent. E.G: 95%.
            minimum_tolerance: str, minimum percentage, E.G: 85%.
            records: dict, origin throughput data with time-throughput matching, E.G from taf.analyzer.aasyslog
            output_dir: str, image file output directory, if None, will use current dir.
            log_name_prefix: str, the prefix of generated chart file.
            time_interval: float, the interval of each traffic data.

        Returns:
            str, The absolute path of generated chart file.
        """
        if records:
            self.records = records
        if not self.records:
            raise ValueError(
                "Origin Records data was not given. "
                "Please input record in either class init or use parameter in generate function."
            )

        logger.info("Start generating image ...")

        self.__generate_validate_values(
            records, theoretical_throughput, average_tolerance, minimum_tolerance, ca
        )
        self.__init_figure_layout()
        self.__add_trace_to_figure(time_interval)
        self.__add_baseline_trace_to_figure(time_interval)

        _tmp_name = self.__init_chart_file_name(direction, log_name_prefix, output_dir)

        offline.plot(self.figure, filename=_tmp_name, auto_open=False)
        logger.info("Image {} generation finished...".format(_tmp_name))

        return _tmp_name

    def __init_chart_file_name(self, direction, log_name_prefix, output_dir):
        date = self.xlist[0].split(".")[0]
        if self.cells[0]:
            tmp_name = "[{date}]_{cell}_{direction}.html".format(date=date, cell=self.cells[0], direction=direction)
        else:
            tmp_name = "[{date}]_{direction}.html".format(date=date, direction=direction)
        if log_name_prefix:
            tmp_name = log_name_prefix + "_" + tmp_name
        if output_dir:
            if os.path.isdir(output_dir):
                tmp_name = os.path.abspath(os.path.join(output_dir, tmp_name))
            else:
                raise ValueError("{} is not a validate directory".format(output_dir))
        return tmp_name

    def __generate_validate_values(
        self, origin_record, target_throughput, target_avg_percent, min_percent, act_ca
    ):
        self.validate_avg = float(target_throughput) * translate_percentage(
            target_avg_percent
        )
        self.validate_min = float(target_throughput) * translate_percentage(min_percent)
        if act_ca:
            self.validate_avg = self.validate_avg / len(origin_record)
            self.validate_min = self.validate_min / len(origin_record)
        return self.validate_avg, self.validate_min

    def __init_figure_layout(self):
        rows = 1
        cols = 1
        self.cells = list(dict.keys(self.records))
        self.cells.sort()
        if len(self.cells) > 1:
            rows = 2
        self.figure = subplots.make_subplots(
            rows=rows,
            cols=cols,
            subplot_titles=("throughput on each cell", "total throughput"),
        )
        self.figure.update_layout(
            yaxis1=dict(ticksuffix="Mbps"),
            yaxis2=dict(ticksuffix="Mbps"),
            title_text="Line chart of throughput",
        )

    def __add_trace_to_figure(self, time_interval):
        for cid in self.cells:
            self.xlist, ylist = self.__get_time_list_and_tput_list_from_records(
                origin_list=self.records[cid],
                time_interval=time_interval
            )
            trace = graph_objs.Scatter(x=self.xlist, y=ylist, mode="lines", name=cid)
            self.figure.add_trace(trace, 1, 1)
            if len(self.xlist) < self.min_cnt:
                self.min_cnt = len(self.xlist)
        validate_avg_line = graph_objs.Scatter(
            x=self.xlist,
            y=[self.validate_avg] * len(self.xlist),
            mode="lines",
            line=dict(dash="dashdot"),
            name="validate_avg",
        )
        self.figure.add_trace(validate_avg_line, 1, 1)
        validate_min_line = graph_objs.Scatter(
            x=self.xlist,
            y=[self.validate_min] * len(self.xlist),
            mode="lines",
            line=dict(dash="dashdot"),
            name="validate_min",
        )
        self.figure.add_trace(validate_min_line, 1, 1)

    def __add_baseline_trace_to_figure(self, time_interval):
        if len(self.cells) > 1:
            xlist_general = self.xlist[: self.min_cnt]
            ylist_general = self.__get_general_pic_data(count=self.min_cnt, time_interval=time_interval)
            trace_general = graph_objs.Scatter(
                x=xlist_general, y=ylist_general, mode="lines", name="general"
            )
            self.figure.add_trace(trace_general, 2, 1)
            validate_avg_general = self.validate_avg * len(self.cells)
            validate_min_general = self.validate_min * len(self.cells)
            validate_avg_general_line = graph_objs.Scatter(
                x=xlist_general,
                y=[validate_avg_general] * len(xlist_general),
                mode="lines",
                line=dict(dash="dashdot"),
                name="validate_avg_general",
            )
            self.figure.add_trace(validate_avg_general_line, 2, 1)
            validate_min_general_line = graph_objs.Scatter(
                x=xlist_general,
                y=[validate_min_general] * len(xlist_general),
                mode="lines",
                line=dict(dash="dashdot"),
                name="validate_min_general",
            )
            self.figure.add_trace(validate_min_general_line, 2, 1)

    def __get_general_pic_data(self, count, time_interval):
        general_tput_list = [0] * count
        for cnt in range(0, count):
            for cid in self.cells:
                tput = convert_bytes_to_mbps_with_time_interval(
                    tput=self.records[cid][cnt]["throughput"],
                    time_interval=time_interval,
                )
                general_tput_list[cnt] = general_tput_list[cnt] + tput
        return general_tput_list

    @staticmethod
    def __get_time_list_and_tput_list_from_records(origin_list, time_interval):
        tput_list = []
        time_list = []
        for data in origin_list:
            tput = convert_bytes_to_mbps_with_time_interval(
                tput=data["throughput"], time_interval=time_interval
            )
            tput_list.append(tput)
            time_list.append(data["record_time"])
        return time_list, tput_list
